CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provisioning_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, integration_name text NOT NULL DEFAULT 'default', token_prefix text NOT NULL, token_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, expires_at timestamptz, revoked_at timestamptz);
CREATE UNIQUE INDEX provisioning_tokens_prefix_idx ON provisioning_tokens(token_prefix) WHERE revoked_at IS NULL;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), external_id text, username text NOT NULL, active boolean NOT NULL DEFAULT true, given_name text, family_name text, formatted_name text, display_name text, title text, department text, user_type text, preferred_language text, employee_number text, organization_name text, division text, cost_center text, manager jsonb NOT NULL DEFAULT '{}', emails jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX users_username_unique ON users(tenant_id,lower(username)) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX users_external_id_unique ON users(tenant_id,external_id) WHERE external_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX users_active_tenant_idx ON users(tenant_id,active) WHERE deleted_at IS NULL;
CREATE TABLE groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), external_id text, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1, UNIQUE(tenant_id,id), UNIQUE(tenant_id,display_name));
CREATE UNIQUE INDEX groups_external_id_unique ON groups(tenant_id,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE group_members (tenant_id uuid NOT NULL, group_id uuid NOT NULL, user_id uuid NOT NULL, PRIMARY KEY(tenant_id,group_id,user_id), FOREIGN KEY(tenant_id,group_id) REFERENCES groups(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE identity_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, issuer text NOT NULL, client_id text NOT NULL, client_secret bytea NOT NULL, redirect_url text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,issuer), UNIQUE(tenant_id,id));
CREATE TABLE identity_links (tenant_id uuid NOT NULL, user_id uuid NOT NULL, provider_id uuid NOT NULL, issuer text NOT NULL, subject text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,issuer,subject), UNIQUE(tenant_id,user_id,provider_id), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,provider_id) REFERENCES identity_providers(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE oidc_login_states (state_hash bytea PRIMARY KEY, provider_id uuid NOT NULL REFERENCES identity_providers(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, nonce text NOT NULL, pkce_verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE app_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, user_id uuid NOT NULL, token_hash bytea NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX app_sessions_user_active_idx ON app_sessions(tenant_id,user_id) WHERE revoked_at IS NULL;
CREATE TABLE roles (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, id text NOT NULL, description text NOT NULL, PRIMARY KEY(tenant_id,id));
CREATE TABLE permissions (tenant_id uuid NOT NULL, id text NOT NULL, description text NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE);
CREATE TABLE role_permissions (tenant_id uuid NOT NULL, role_id text NOT NULL, permission_id text NOT NULL, PRIMARY KEY(tenant_id,role_id,permission_id), FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,permission_id) REFERENCES permissions(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE group_role_mappings (tenant_id uuid NOT NULL, group_id uuid NOT NULL, role_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,group_id,role_id), FOREIGN KEY(tenant_id,group_id) REFERENCES groups(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, occurred_at timestamptz NOT NULL DEFAULT now(), actor_type text NOT NULL, actor_id text, action text NOT NULL, resource_type text, resource_id text, outcome text NOT NULL DEFAULT 'success', request_id text, details jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_events_tenant_time_idx ON audit_events(tenant_id,occurred_at DESC);
CREATE INDEX audit_events_resource_idx ON audit_events(tenant_id,resource_type,resource_id,occurred_at DESC);
